styles.tutorial:
section[data-skill-hub] .-w {
  height: calc( var(--vh,1vh) * 1200 );
  contain: paint;
}
section[data-skill-hub] .-w div {
  display: grid;
  margin-left: calc( 50% + var(--g-gap));
  position: sticky;
  top: calc( var(--vh,1vh) * 50 );
  transform-origin: calc( var(--g-gap) * -0.5) 50%;
  rotate: calc( 4 * -360deg * var(--progress) );
}
section[data-skill-hub] .-w div > span {
  grid-area: 1/1;
  display: block;
  text-transform: capitalize;
  transform-origin: 0% 50%;
  transform: rotate(calc(var(--order) * 360deg / var(--total))) translate( calc( var(--total) * 0.2em), 0);
  translate: calc( var(--g-gap) * -0.5 ) 0;
}
section[data-skill-hub] .-w div > span:first-child {
  color: var(--c-red);
}

section[data-skill-hub] .-s-char {
  rotate: calc( pow(var(--char-index),1.75) * var(--lerp) * 0.1deg);
  translate: calc( pow(var(--char-index),1.75) * abs(var(--lerp)) * -0.00125em ) calc( pow(var(--char-index),1.75) * var(--lerp) * 0.0025em );
}

@media (min-width: 1024px) {}
